<script setup lang="ts">import {ref,computed,onMounted,onUnmounted,watch} from 'vue';import {route} from '../router';import {runs} from '../stores/runs';import {reviews} from '../stores/reviews';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import EmptyState from '../components/common/EmptyState.vue';import StatusPill from '../components/common/StatusPill.vue';import ProbabilitySummary from '../components/ProbabilitySummary.vue';import PosteriorBars from '../components/PosteriorBars.vue';import InformationRanking from '../components/InformationRanking.vue';import NetworkDiagram from '../components/NetworkDiagram.vue';import BranchTable from '../components/BranchTable.vue';import EliminationTrace from '../components/EliminationTrace.vue';import CptTable from '../components/CptTable.vue';const selected=ref(route.value.query.get('run')||'demo-run'),candidate=ref(''),action=ref('已核对不可变CPT版本、证据logZ、后验与候选分支；极小正概率下溢不等于不可能，只按给定模型研修。'),notice=ref('');const {error,busy,act}=useTask();watch(()=>route.value.query.get('run'),v=>selected.value=v||'demo-run');let timer:ReturnType<typeof setInterval>;onMounted(()=>{runs.load();timer=setInterval(runs.load,2000)});onUnmounted(()=>clearInterval(timer));const run=computed(()=>runs.items.value.find(r=>r.id===selected.value)),result=computed(()=>run.value?.result),branch=computed(()=>result.value?.analysis.candidates.find((c:any)=>c.node_id===(candidate.value||result.value.analysis.candidates[0]?.node_id)));function submit(){act(async()=>{await reviews.create({run_id:selected.value,action:action.value});notice.value='证据推理复核已提交，等待主管批准。'})}</script><template><PageHeading index="04 / 推理底稿" title="后验有分母，每次消元都有迹可查。" note="只在logZ=−∞判定不可能。exp(logZ)下溢另标注；熵用log₂，概率/对数概率/原始IG和CPT版本均锁定。"/><div class="run-toolbar"><label>运行记录<select v-model="selected"><option v-for="r in runs.items.value" :key="r.id" :value="r.id">{{r.id==='demo-run'?'CY-07 联合证据':r.id.slice(0,8)}} · {{r.status}}</option></select></label><StatusPill v-if="run" :status="run.status"/></div><Notice :message="error||runs.error.value"/><Notice v-if="run?.status==='failed'" :message="run.error"/><EmptyState v-if="run&&['queued','running'].includes(run.status)" text="Redis worker正在执行log因子消元与候选分支推理，每两秒刷新。"/><template v-if="run?.status==='completed'&&result"><ProbabilitySummary :result="result"/><p class="version-note">{{result.network_name}} / CPT {{result.version}} / {{result.case_name}}</p><div class="inference-layout"><section><PosteriorBars :inference="result.analysis.baseline"/><NetworkDiagram :nodes="result.snapshot.nodes" :evidence="result.snapshot.evidence" :target="result.snapshot.target"/></section><aside class="evidence-note"><InformationRanking :rows="result.analysis.candidates" :selected="branch?.node_id" @select="candidate=$event"/><p class="hash-note">输入SHA256 {{result.input_sha256}}</p></aside></div><BranchTable v-if="branch" :candidate="branch"/><EliminationTrace :inference="result.analysis.baseline"/><details class="cpt-details"><summary>查看本次锁定的完整CPT</summary><CptTable :nodes="result.snapshot.nodes" :rows="result.snapshot.cpt"/></details><p class="method-note">{{result.analysis.note}}<br>{{result.assumptions}}</p><form v-if="canWrite()" class="review-form" @submit.prevent="submit"><label>证据复核说明<textarea v-model="action" rows="4" required minlength="8"></textarea></label><button :disabled="busy">提交证据推理复核</button><p class="success" v-if="notice">{{notice}}</p></form></template></template>
